## 7. 关键代码片段

### 7.1 创建牌组（2副牌108张）

```javascript
createDeck() {
    const deck = [];
    const levelRank = LEVEL_TO_RANK[this.gameState.teamLevels[this.gameState.currentAttackTeam]];

    // 2副牌
    for (let i = 0; i < 2; i++) {
        for (const suit of SUITS) {
            for (const rank of RANKS) {
                deck.push({
                    suit, 
                    rank, 
                    value: RANK_VALUES[rank],
                    isJoker: false,
                    isLevelCard: rank === levelRank,
                    score: SCORE_CARDS[rank] || 0  // 分值
                });
            }
        }
        // 大小王
        deck.push({ suit: '🃏', rank: '小王', value: 15, isJoker: true, score: 0 });
        deck.push({ suit: '🃏', rank: '大王', value: 16, isJoker: true, score: 0 });
    }
    return deck;
}
```

### 7.2 发牌

```javascript
dealCards() {
    const deck = this.shuffle(this.createDeck());
    const hands = {};
    const playerIds = this.getSortedPlayerIds();

    // 每人25张
    for (let i = 0; i < 4; i++) {
        hands[playerIds[i]] = deck.slice(i * 25, (i + 1) * 25);
        this.sortHand(hands[playerIds[i]]);
    }

    // 8张底牌
    this.gameState.bottomCards = deck.slice(100, 108);

    return hands;
}
```

### 7.3 连对判断

```javascript
isConsecutivePairs(cards, levelRank) {
    if (cards.length < 4 || cards.length % 2 !== 0) return false;

    // 按点数分组
    const groups = {};
    cards.forEach(c => {
        if (!c.isJoker && c.rank !== levelRank) {  // 排除王和级牌
            groups[c.rank] = (groups[c.rank] || 0) + 1;
        }
    });

    const ranks = Object.keys(groups).sort((a, b) => RANK_VALUES[a] - RANK_VALUES[b]);

    // 每个点数必须是2张以上
    for (const rank of ranks) {
        if (groups[rank] < 2) return false;
    }

    // 检查连续性
    for (let i = 1; i < ranks.length; i++) {
        if (RANK_VALUES[ranks[i]] - RANK_VALUES[ranks[i-1]] !== 1) {
            return false;
        }
    }

    return ranks.length >= 2;
}
```

