function handleGameState(state) {
    gameState = state;

    // 更新分数
    document.getElementById('team1Score').textContent = state.scores.team1;
    document.getElementById('team2Score').textContent = state.scores.team2;
    document.getElementById('team1Level').textContent = LEVEL_TO_RANK[state.teamLevels[1]];
    document.getElementById('team2Level').textContent = LEVEL_TO_RANK[state.teamLevels[2]];

    // 更新主花色
    document.getElementById('trumpSuit').textContent = state.trumpSuit || '-';
    document.getElementById('trumpRank').textContent = state.trumpRank || '2';

    // 更新玩家信息
    updatePlayerAreas(state);

    // 更新手牌数量
    for (const pid in state.hands) {
        const count = state.hands[pid].count;
        const info = state.playerInfo[pid];
        // 根据座位更新显示
    }

    // 检查是否轮到自己
    const playerIds = Object.keys(state.playerInfo).sort((a, b) =>
        state.playerInfo[a].playerNum - state.playerInfo[b].playerNum
    );
    const currentPlayerId = playerIds[state.currentPlayer];

    if (currentPlayerId === myPlayerId && state.phase === 'playing') {
        document.getElementById('playBtn').disabled = false;
        document.getElementById('passBtn').disabled = !state.leadCards;
    } else {
        document.getElementById('playBtn').disabled = true;
        document.getElementById('passBtn').disabled = true;
    }

    // 高亮当前玩家
    document.querySelectorAll('.player-info').forEach(el => el.classList.remove('current-turn'));
}

function updatePlayerAreas(state) {
    const playerIds = Object.keys(state.playerInfo).sort((a, b) =>
        state.playerInfo[a].playerNum - state.playerInfo[b].playerNum
    );

    const positions = ['opponentTop', 'opponentRight', 'myArea', 'opponentLeft'];
    const myPlayerNum = state.playerInfo[myPlayerId]?.playerNum || 1;

    for (let i = 0; i < 4; i++) {
        const pid = playerIds[i];
        const info = state.playerInfo[pid];
        const relativePos = (info.playerNum - myPlayerNum + 4) % 4;
        const posId = positions[relativePos];

        if (posId !== 'myArea') {
            const nameEl = document.querySelector(`#${posId} .player-name`);
            const countEl = document.querySelector(`#${posId} .player-cards-count`);
            if (nameEl) nameEl.textContent = info.name;
            if (countEl) countEl.textContent = `${state.hands[pid]?.count || 0}张`;
        }
    }
}

