// ==================== 叫主 ====================
function handleBiddingStart(data) {
    gameState = data.gameState;
    document.getElementById('biddingPanel').style.display = 'block';
    document.getElementById('currentBidInfo').textContent = '无';

    checkBiddingTurn();
}

function handleNextBidder(data) {
    gameState.currentBidder = data.currentBidder;
    checkBiddingTurn();
}

function checkBiddingTurn() {
    const playerIds = Object.keys(gameState.playerInfo).sort((a, b) =>
        gameState.playerInfo[a].playerNum - gameState.playerInfo[b].playerNum
    );
    const currentBidderId = playerIds[gameState.currentBidder];

    if (currentBidderId === myPlayerId) {
        document.getElementById('biddingInfo').textContent = '轮到你叫主';
    } else {
        document.getElementById('biddingInfo').textContent = `等待 ${gameState.playerInfo[currentBidderId]?.name} 叫主`;
    }
}

let selectedBidSuit = null;

function bid(suit) {
    selectedBidSuit = suit;
    document.querySelectorAll('.suit-btn').forEach(btn => btn.style.borderColor = '#555');
    event.target.style.borderColor = '#ffd700';
}

function confirmBid() {
    if (!selectedBidSuit) {
        showMessage('请选择花色');
        return;
    }

    const count = parseInt(document.getElementById('bidCount').value);
    send({
        type: 'bid',
        suit: selectedBidSuit,
        count
    });
}

function passBid() {
    send({ type: 'passBid' });
}

function handleBidWinner(data) {
    document.getElementById('biddingPanel').style.display = 'none';
    showMessage(`${data.winnerName} 叫主成功，主花色: ${data.trumpSuit}`);
    document.getElementById('trumpSuit').textContent = data.trumpSuit;
}

// ==================== 扣底 ====================

